/**
 * Tipos das classes de `pagina.module.css`. Escrito à mão pelo mesmo motivo dos
 * outros módulos de estilo: a declaração injetada é assinatura de índice, e nome de
 * classe errado compilaria.
 */
declare const estilo: {
  readonly grupo: string;
  readonly grupoTitulo: string;
  readonly pagina: string;
  readonly porta: string;
  readonly portaDescricao: string;
  readonly portaTitulo: string;
  readonly portas: string;
  readonly subtitulo: string;
  readonly titulo: string;
};

export default estilo;
